// Stable fingerprint of a list of prompt strings (FNV-1a, 32-bit, hex).
// Used to detect stale image_reaction_profiles: the hash of the preprocessing
// steps' prompts is stored with each profile; when the current prompts hash
// differently, the profile was generated by an older prompt version.
export const promptHash = (parts: string[]): string => {
  let hash = 0x811c9dc5
  // NUL separator so a part boundary can't be faked by moving text across it
  const text = parts.join('\u0000')
  for (let i = 0; i < text.length; i += 1) {
    hash = Math.imul(hash ^ text.charCodeAt(i), 0x01000193)
  }
  return (hash >>> 0).toString(16).padStart(8, '0')
}
